    new RegExp(
      `^[ \\t]*${COMMENT}\\s*${CONFIRM}:[^\\n]*\\n(?=[ \\t]*(?:${OWNER_KEYS})\\s*:\\s*\\{)`,
      'm',
    ),
    '',
